dsl:
name: pool
bar: 1h
strategy_pool:
  members:
    - {id: a, strategy: s_a}
    - {id: s, strategy: s_s}
    - {id: c, strategy: s_c}
  allocation:
    method: rotation
    rotation: {top: 1, factors: [{name: return, window: 3}, {name: drawdown, window: 4}]}
  timing: {window: 3}
  step: 0.5
  fees: {spot_bps: 10, swap_bps: 5}
